def apply_pattern(test_input):
    """
    Apply pattern transformation.

    The special cell's position determines the right-side offset.
    - If special column is at the left wall (0), alternating rows get (0, 1)
    - Otherwise, alternating rows get (c-1, c, c+1)
    """
    height, width = len(test_input), len(test_input[0])

    # Find special cell (8)
    for r in range(height):
        for c in range(width):
            if test_input[r][c] == 8:
                special_r, special_c = r, c

    # Create output grid filled with 0s
    output = [[0] * width for _ in range(height)]

    for dr in range(height - special_r):
        row = special_r + dr

        if dr % 2 == 1:
            # Odd row offset (alternating)
            if special_c == 0:
                # Left wall - get (0, 1)
                output[row][0] = 1
                if 1 < width:
                    output[row][1] = 1
            else:
                # Otherwise get (c-1, c, c+1)
                if special_c - 1 >= 0:
                    output[row][special_c - 1] = 1
                output[row][special_c] = 1
                if special_c + 1 < width:
                    output[row][special_c + 1] = 1
        else:
            # Even row offset (adjacent) - just center column
            output[row][special_c] = 1

    return output

